#!/usr/bin/env python3
"""Replace only the SimpleHEMS calendar UI, backup and build with rollback."""
import argparse, datetime, pathlib, re, shutil, subprocess, tarfile, sys
COMPONENT = 'function CalendarPage() {\n  const [data, setData] = useState({ events: [], status: {} });\n  const [error, setError] = useState("");\n  const [monthOffset, setMonthOffset] = useState(0);\n  const [selected, setSelected] = useState("");\n  const refs = useRef({});\n  const scrollRef = useRef(null);\n  const pageRef = useRef(null);\n  const dateKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;\n  const parseDay = value => { const [y,m,d] = String(value).slice(0,10).split("-").map(Number); return new Date(y,m-1,d); };\n  const today = dateKey(new Date());\n  const dayOnly = value => String(value || "").slice(0,10);\n  useEffect(() => {\n    let stopped = false;\n    const load = async () => {\n      try { const result = await api("/api/calendar"); if (!stopped) { setData(result); setError(""); } }\n      catch(e) { if (!stopped) setError(String(e.message || e)); }\n    };\n    load(); const timer = setInterval(load, 60000);\n    const focus = () => load(); window.addEventListener("focus", focus);\n    const main = pageRef.current?.closest("main");\n    const shell = main?.closest(".shell");\n    main?.classList.add("ttCalendarMain"); shell?.classList.add("ttCalendarShell");\n    return () => { stopped = true; clearInterval(timer); window.removeEventListener("focus",focus); main?.classList.remove("ttCalendarMain"); shell?.classList.remove("ttCalendarShell"); };\n  }, []);\n  const events = (Array.isArray(data.events) ? data.events : []).filter(e => /^\\d{4}-\\d{2}-\\d{2}/.test(String(e.start)) && /^\\d{4}-\\d{2}-\\d{2}/.test(String(e.end)));\n  const byDate = {};\n  events.forEach(event => {\n    const first = dayOnly(event.start) < today ? today : dayOnly(event.start);\n    const last = dayOnly(event.end);\n    if (last < first) return;\n    let d = parseDay(first), end = parseDay(last);\n    while (d <= end) { const key = dateKey(d); (byDate[key] ||= []).push(event); d.setDate(d.getDate()+1); }\n  });\n  const dates = Object.keys(byDate).sort();\n  const now = new Date();\n  const base = new Date(now.getFullYear(), now.getMonth()+monthOffset, 1);\n  const jump = key => {\n    const target = refs.current[key]; if (!target || key < today) return;\n    setSelected(key);\n    if (window.matchMedia("(min-width: 1024px)").matches && scrollRef.current) {\n      const scroller = scrollRef.current;\n      const top = scroller.scrollTop + target.getBoundingClientRect().top - scroller.getBoundingClientRect().top - 16;\n      scroller.scrollTo({ top: Math.max(0,top), behavior: "smooth" });\n    } else target.scrollIntoView({ behavior: "smooth", block: "start" });\n  };\n  const color = e => /^#[0-9a-f]{3,8}$/i.test(e.color || "") ? e.color : "#38bdf8";\n  const heading = key => { const d=parseDay(key); return `${d.getMonth()+1}月${d.getDate()}日（${"日月火水木金土"[d.getDay()]}）`; };\n  const shortDate = key => { const d=parseDay(key); return `${d.getMonth()+1}/${d.getDate()}`; };\n  const monthView = index => {\n    const d = new Date(base.getFullYear(),base.getMonth()+index,1), y=d.getFullYear(), m=d.getMonth();\n    const cells = Array(d.getDay()).fill(null);\n    for(let n=1;n<=new Date(y,m+1,0).getDate();n++) cells.push(n);\n    while(cells.length%7) cells.push(null);\n    return <div className={`tt2Month tt2Month${index}`} key={`${y}-${m}`}>\n      <h3>{y}年{m+1}月</h3>\n      <div className="tt2Week">{"日月火水木金土".split("").map((v,i)=><span key={v} className={i===0?"sun":i===6?"sat":""}>{v}</span>)}</div>\n      <div className="tt2Grid" style={{gridTemplateRows:`repeat(${cells.length/7},minmax(0,1fr))`}}>{cells.map((n,i)=>{\n        if(!n) return <span key={`blank-${i}`} />;\n        const key=dateKey(new Date(y,m,n)), list=byDate[key]||[], enabled=key>=today&&list.length>0;\n        const colors=[...new Set(list.map(color))].slice(0,3);\n        return <button type="button" key={key} disabled={!enabled} onClick={()=>jump(key)} aria-label={`${heading(key)} ${list.length}件`} className={`${key===today?"today":""} ${key===selected?"selected":""} ${key<today?"past":""}`}>\n          <span>{n}</span><small>{colors.map(c=><i key={c} style={{background:c}} />)}</small>\n        </button>;\n      })}</div>\n    </div>;\n  };\n  return <div className="tt2Page" ref={pageRef}>\n    <div className="tt2Navigation">\n      <div className="tt2MonthControls"><button type="button" onClick={()=>setMonthOffset(v=>v-1)} aria-label="前月">‹</button><button type="button" onClick={()=>setMonthOffset(0)}>今月</button><button type="button" onClick={()=>setMonthOffset(v=>v+1)} aria-label="翌月">›</button></div>\n      <div className="tt2Months">{[0,1,2].map(monthView)}</div>\n      <div className="tt2Status">{error || (data.status?.ok===false ? `同期エラー：${data.status.message||""}` : `最終同期：${data.status?.checked_at ? new Date(data.status.checked_at).toLocaleString("ja-JP") : "未取得"}`)}</div>\n    </div>\n    <div className="tt2Scroll" ref={scrollRef} tabIndex={0} aria-label="日別予定一覧">\n      <div className="tt2List">\n        <div className="tt2ListTitle"><h2>予定一覧</h2><button type="button" onClick={()=>dates.length&&jump(dates[0])}>直近の予定へ</button></div>\n        {!dates.length&&<div className="tt2Empty">今日以降の予定がありません。</div>}\n        {dates.map(key=><div key={key} ref={el=>{refs.current[key]=el;}} className={`tt2Day ${selected===key?"selected":""}`}>\n          <div className="tt2DayHeading"><div><h3>{heading(key)}</h3><small>{byDate[key].length}件の予定</small></div>{key===today&&<span className="tt2TodayBadge">今日</span>}</div>\n          <div className="tt2Events">{[...byDate[key]].sort((a,b)=>Number(b.allDay)-Number(a.allDay)||String(a.start).localeCompare(String(b.start))).map((e,index)=>{\n            const long=dayOnly(e.end)>dayOnly(e.start), first=dayOnly(e.start), last=dayOnly(e.end);\n            const day=Math.round((parseDay(key)-parseDay(first))/86400000)+1, total=Math.round((parseDay(last)-parseDay(first))/86400000)+1;\n            return <div key={`${e.id}-${index}`} className={`tt2Event ${long?"long":""}`} style={{borderLeftColor:color(e)}}>\n              <div className="tt2Time">{e.allDay?"終日":String(e.start).slice(11,16)}</div>\n              <div className="tt2EventBody"><strong>{e.title}</strong>{long&&<small>{shortDate(first)} ～ {shortDate(last)} ・ {day}日目 / 全{total}日</small>}{e.location&&<small>{e.location}</small>}</div>\n              <span className="tt2Owner">{e.owner||"対象者未設定"}</span>\n            </div>;\n          })}</div>\n        </div>)}\n      </div>\n    </div>\n  </div>;\n}\n'
CSS = '\n/* TT_CALENDAR_V2_BEGIN */\n.tt2Page{display:block;min-width:0;color:#f2f7fc}.tt2Page button{font-family:inherit;cursor:pointer}.tt2Navigation{position:static;display:flex;flex-direction:column;gap:12px;min-height:0;min-width:0;padding:14px;border:1px solid #244057;border-radius:16px;background:#091a2b}.tt2MonthControls{display:flex;justify-content:space-between;align-items:center;gap:12px;flex:none}.tt2MonthControls button,.tt2ListTitle button{border:1px solid #31516b;border-radius:9px;background:#122b40;color:#d9e8f6;padding:7px 14px}.tt2MonthControls button:first-child,.tt2MonthControls button:last-child{font-size:24px;line-height:1}.tt2Months{display:block;min-height:0}.tt2Month{display:flex;flex-direction:column;min-height:0;padding:10px;border:1px solid #244057;border-radius:12px;background:#0d2134}.tt2Month h3{margin:0 0 10px;text-align:center;font-size:15px}.tt2Week,.tt2Grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;text-align:center}.tt2Week{font-size:11px;color:#a3b7c9;margin-bottom:6px}.tt2Week .sun{color:#fb7185}.tt2Week .sat{color:#7dd3fc}.tt2Grid{flex:1;min-height:0}.tt2Grid button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-width:0;min-height:38px;border:1px solid transparent;border-radius:8px;background:#17334c;color:#edf6ff;font-size:13px;padding:4px}.tt2Grid button:disabled{background:transparent;color:#71899f;cursor:default}.tt2Grid button.past{opacity:.55}.tt2Grid button.today{border-color:#2dd4bf;color:#5eead4}.tt2Grid button.selected{box-shadow:inset 0 0 0 1px #38bdf8}.tt2Grid small{display:flex;gap:3px;height:5px}.tt2Grid i{width:5px;height:5px;border-radius:50%;display:block}.tt2Month1,.tt2Month2{display:none}.tt2Status{font-size:11px;color:#9eb3c6;overflow-wrap:anywhere;flex:none}.tt2Scroll{position:relative;min-width:0;padding:16px 0;overflow:visible}.tt2List{display:grid;gap:16px;max-width:1050px;margin:auto;padding-bottom:24px}.tt2ListTitle{display:flex;align-items:center;justify-content:space-between;gap:12px}.tt2ListTitle h2{margin:0;font-size:20px}.tt2Day{border:1px solid #29455d;border-radius:16px;overflow:hidden;background:#0b1e30;scroll-margin-top:16px}.tt2Day.selected{border-color:#38bdf8}.tt2DayHeading{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;border-bottom:1px solid #244057}.tt2DayHeading h3{margin:0;font-size:18px}.tt2DayHeading small{display:block;color:#9ab0c3;margin-top:5px}.tt2TodayBadge{background:#2dd4bf;color:#08212a;border-radius:12px;padding:4px 10px;font-size:12px;font-weight:bold}.tt2Events{display:grid;gap:10px;padding:14px}.tt2Event{display:grid;grid-template-columns:64px minmax(0,1fr) auto;gap:12px;align-items:center;padding:13px;border-left:5px solid;border-radius:10px;background:#122b40}.tt2Event.long{background:#173149}.tt2Time{font-size:13px;font-weight:bold}.tt2EventBody strong{display:block;overflow-wrap:anywhere}.tt2EventBody small{display:block;color:#a6bbcd;font-size:12px;margin-top:5px}.tt2Owner{font-size:12px;color:#c7d8e8;overflow-wrap:anywhere}.tt2Empty{padding:25px;border:1px solid #29455d;border-radius:14px;color:#a6bbcd}\n@media(min-width:1024px){.shell.ttCalendarShell{height:100dvh;min-height:0;overflow:hidden}.shell.ttCalendarShell>main.ttCalendarMain{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;margin:0 auto;padding:22px 24px;overflow:hidden}.ttCalendarMain>header{flex:none;margin-bottom:18px}.ttCalendarMain>.error{flex:none}.tt2Page{flex:1;min-height:0;display:grid;grid-template-columns:300px minmax(0,1fr);gap:20px;overflow:hidden}.tt2Navigation{height:100%;overflow:hidden}.tt2Months{display:grid;grid-template-rows:repeat(3,minmax(0,1fr));gap:10px;flex:1;min-height:0}.tt2Month1,.tt2Month2{display:flex}.tt2Month h3{font-size:13px;margin-bottom:5px}.tt2Week{font-size:10px;margin-bottom:4px}.tt2Grid{gap:2px}.tt2Grid button{min-height:0;font-size:11px;padding:1px;gap:1px}.tt2Scroll{height:100%;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:0 8px 0 0;scrollbar-gutter:stable}.tt2List{padding:2px 2px 32px}.tt2Status{font-size:10px}}\n@media(min-width:1400px){.tt2Page{grid-template-columns:330px minmax(0,1fr)}}\n@media(max-width:600px){.tt2Event{grid-template-columns:55px minmax(0,1fr);gap:8px}.tt2Owner{grid-column:2}.tt2ListTitle button{font-size:12px;padding:7px}.tt2DayHeading h3{font-size:16px}}\n/* TT_CALENDAR_V2_END */\n'
def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--app',default='/home/hems/simplehems-server-v2')
    parser.add_argument('--no-build',action='store_true',help='Only patch source (testing)')
    args=parser.parse_args()
    app=pathlib.Path(args.app).resolve(); frontend=app/'frontend'
    src=frontend/'src.jsx'; style=frontend/'style.css'
    original=src.read_text(encoding='utf-8'); oldcss=style.read_text(encoding='utf-8')
    start=original.find('function CalendarPage(')
    end=original.find('function Side(',start)
    if start<0 or end<0: raise RuntimeError('CalendarPage/Side boundaries not found; no changes made')
    if not args.no_build and not shutil.which('npm'): raise RuntimeError('npm not found; no changes made')
    stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    backup=app.parent/('simplehems-calendar-backup-'+stamp+'.tar.gz')
    with tarfile.open(backup,'w:gz') as archive:
        for name in ('src.jsx','style.css','dist'):
            path=frontend/name
            if path.exists(): archive.add(path,arcname=name)
    print('Backup:',backup,flush=True)
    try:
        src.write_text(original[:start]+COMPONENT+'\n'+original[end:],encoding='utf-8')
        cleaned=re.sub(r'/\* TT_CALENDAR_V2_BEGIN \*/.*?/\* TT_CALENDAR_V2_END \*/','',oldcss,flags=re.S)
        style.write_text(cleaned+CSS,encoding='utf-8')
        if not args.no_build: subprocess.run(['npm','run','build'],cwd=frontend,check=True)
    except Exception:
        src.write_text(original,encoding='utf-8'); style.write_text(oldcss,encoding='utf-8')
        dist=frontend/'dist'
        if dist.exists(): shutil.rmtree(dist)
        with tarfile.open(backup,'r:gz') as archive:
            for member in archive.getmembers():
                if member.name=='dist' or member.name.startswith('dist/'):
                    archive.extract(member,frontend,filter='data')
        print('Build failed; source and dist restored.',file=sys.stderr)
        raise
    print('Calendar UI updated. Reload browser. Backend restart not required.')
if __name__=='__main__': main()
